const rows = $input.all().map(i => i.json);

const toNull = v => (v === undefined || v === null || String(v).trim() === '' || String(v).trim() === 'N/A') ? null : String(v).trim();

const cleaned = rows.map(r => ({
  rank: parseInt(r.Rank, 10),
  name: toNull(r.Name),
  platform: toNull(r.Platform),
  year: toNull(r.Year) === null ? null : parseInt(r.Year, 10),
  genre: toNull(r.Genre),
  publisher: toNull(r.Publisher),
  na_sales: parseFloat(r.NA_Sales),
  eu_sales: parseFloat(r.EU_Sales),
  jp_sales: parseFloat(r.JP_Sales),
  other_sales: parseFloat(r.Other_Sales),
  global_sales: parseFloat(r.Global_Sales),
}));

// Fail loudly on bad rows instead of loading them
const bad = cleaned.filter(r =>
  !r.name || !r.platform || !r.genre ||
  [r.na_sales, r.eu_sales, r.jp_sales, r.other_sales, r.global_sales].some(Number.isNaN)
);
if (bad.length > 0) {
  throw new Error(`${bad.length} bad rows, first: ${JSON.stringify(bad[0])}`);
}

return cleaned.map(r => ({ json: r }));

const EXPECTED = 16598;
const actual = $input.first().json.row_count;
if (actual !== EXPECTED) {
  throw new Error(`Row count check failed: expected ${EXPECTED}, got ${actual}`);
}
return [{ json: { ok: true, row_count: actual } }];
